fn linked_list(&mut self, ring: &[[f64;2]], clockwise: bool) -> Option<usize> {
    let len = ring.len();
    let mut sum = 0.0;
    let mut j = if len > 0 { len - 1 } else { 0 };
    for i in 0..len {
        sum += (ring[j][0] - ring[i][0]) * (ring[i][1] + ring[j][1]);
        j = i;
    }
    let mut last: Option<usize> = None;
    if clockwise == (sum > 0.0) {
        for i in 0..len {
            last = Some(self.insert_node((self.vertices + i) as u32, ring[i][0], ring[i][1], last));
        }
    } else {
        for i in (0..len).rev() {
            last = Some(self.insert_node((self.vertices + i) as u32, ring[i][0], ring[i][1], last));
        }
    }
    if let Some(l) = last {
        let ln = self.nodes[l].next;
        if equals(&self.nodes[l], &self.nodes[ln]) {
            self.remove_node(l);
            last = Some(self.nodes[l].next); // careful: after remove, nodes[l].next still old next
        }
    }
    self.vertices += len;
    last
}
