```rust
fn sort_linked(&mut self, list: usize) -> usize {
    let mut in_size = 1usize;
    let mut list = Some(list);
    loop {
        let mut p = list;
        list = None;
        let mut tail: Option<usize> = None;
        let mut num_merges = 0;
        while let Some(pi) = p {
            num_merges += 1;
            let mut q = Some(pi);
            let mut p_size = 0;
            for _ in 0..in_size {
                p_size += 1;
                q = self.nodes[q.unwrap()].next_z;
                if q.is_none() { break; }
            }
            let mut q_size = in_size;
            while p_size > 0 || (q_size > 0 && q.is_some()) {
                let e: usize;
                if p_size != 0 && (q_size == 0 || q.is_none() || self.nodes[p.unwrap()].z <= self.nodes[q.unwrap()].z) {
                    e = p.unwrap();
                    p = self.nodes[e].next_z;
                    p_size -= 1;
                } else {
                    e = q.unwrap();
                    q = self.nodes[e].next_z;
                    q_size -= 1;
                }
                match tail {
                    Some(t) => self.nodes[t].next_z = Some(e),
                    None => list = Some(e),
                }
                self.nodes[e].prev_z = tail;
                tail = Some(e);
            }
            p = q;
        }
        self.nodes[tail.unwrap()].next_z = None;
        in_size *= 2;
        if num_merges <= 1 { break; }
    }
    list.unwrap()
}
```

