//! A Rust port of the Mapbox `earcut` polygon triangulation algorithm
//! (ear clipping with z-order hashing), matching the behavior of
//! `mapbox::earcut<uint32_t>` from earcut.hpp.

const THRESHOLD: usize = 80;

#[derive(Clone)]
struct Node {
    i: u32,
    x: f64,
    y: f64,
    z: i32,
    prev: usize,
    next: usize,
    prev_z: Option<usize>,
    next_z: Option<usize>,
    steiner: bool,
}

pub struct Earcut {
    nodes: Vec<Node>,
    pub indices: Vec<u32>,
    vertices: usize,
    min_x: f64,
    min_y: f64,
    inv_size: f64,
}

pub fn earcut(polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let mut e = Earcut::new();
    e.run(polygon);
    e.indices
}
